import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    cnt = {}
    for x in data[1:1 + n]:
        v = int(x)
        cnt[v] = cnt.get(v, 0) + 1
    best_v, best_c = None, 0
    for v, c in cnt.items():
        if c > best_c or (c == best_c and v < best_v):
            best_v, best_c = v, c
    print(best_v)

main()

